#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#define string_count 10 

static const char* strings[string_count] = {


	"",

	"",


	"",


	"",


	"",


	"",


	"",


	"",


	"",


	"",




};



int main(void) {

	char output[1024] = {0};

	int n = (int) strlen(strings[0]);

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < string_count; j++) {
			char bit = (strings[j])[i] - '0';
			output[i] += bit;
		}
	}

	for (int i = 0; i < n; i++) 
		output[i] += '0';

	for (int k = 0; k < 5; k++) {
		const int start = k * 200;
		const int end = (k + 1) * 200;
		for (int i = 0; i < string_count; i++) {
			for (int j = start; j < end; j++) {
				putchar(strings[i][j]);
			} puts("");
		}
		puts("\n");
		for (int j = start; j < end; j++) {
			putchar(output[j]); 
		} puts("");
		puts("\n\n\n\n\n\n");
	}
}






























